# Feature engineering code for mpg.csv, generated by openai:gpt-6.1-sol
# (generated (attempt 1)). Batch-stateless: run it on a batch and align the result to feature_columns in best_pipeline.joblib.

import pandas as pd
import numpy as np
import re


def engineer_features(df: pd.DataFrame, target_column: str) -> pd.DataFrame:
    out = df[[target_column]].copy()
    numeric = {}
    feature_count = 0
    known_measurements = {'cylinders', 'displacement', 'horsepower', 'weight', 'acceleration', 'model_year'}

    def clean(s):
        s = pd.to_numeric(s, errors='coerce').astype('float64')
        s = s.replace([np.inf, -np.inf], np.nan)
        median = s.median() if s.notna().any() else 0.0
        return s.fillna(median)

    def add(label, values):
        nonlocal feature_count
        if feature_count >= 500:
            return
        name = 'feature_' + str(feature_count) + '_' + str(label)
        while name in out.columns:
            name += '_'
        out[name] = clean(values)
        feature_count += 1

    for col in df.columns:
        if col == target_column:
            continue
        s = df[col]
        label = str(col)
        key = label.lower().strip()
        n_unique = s.nunique(dropna=True)
        if key == 'name':
            continue
        if len(df) > 1 and n_unique == len(df) and key not in known_measurements:
            continue
        if re.search(r'(^|_)(id|uuid|vin)($|_)', key):
            continue

        if pd.api.types.is_numeric_dtype(s.dtype):
            values = clean(s)
            numeric[key] = values
            add(label, values)
            continue

        is_date = pd.api.types.is_datetime64_any_dtype(s.dtype)
        date_named = bool(re.search(r'(^|_)(date|datetime|timestamp)($|_)', key))
        if is_date or date_named:
            dates = pd.to_datetime(s, errors='coerce', utc=True, format='mixed')
            if is_date or dates.notna().mean() >= 0.8:
                add(label + '_year', dates.dt.year)
                add(label + '_month', dates.dt.month)
                add(label + '_weekday', dates.dt.dayofweek)
                continue

        text = s.astype('string').fillna('__missing__')
        levels = text.unique()
        if len(levels) <= 20:
            for level in sorted(levels.tolist()):
                add(label + '_' + str(level), text.eq(level).astype('int8'))
        elif n_unique / max(len(df), 1) <= 0.5:
            frequency = text.value_counts(normalize=True)
            add(label + '_frequency', text.map(frequency))

    if 'horsepower' in numeric and 'weight' in numeric:
        denominator = numeric['weight'].where(numeric['weight'] > 0)
        add('horsepower_per_weight', numeric['horsepower'] / denominator)
    if 'displacement' in numeric and 'cylinders' in numeric:
        denominator = numeric['cylinders'].where(numeric['cylinders'] > 0)
        add('displacement_per_cylinder', numeric['displacement'] / denominator)

    return out
